def compute_sumset_size(T):
    sums = set()
    N = len(T)
    for i in range(N):
        for j in range(i, N):
            sums.add(T[i] + T[j])
    return len(sums)

# T_uniform = {0} union {odd integers from 1 to 171}
T_uniform = [0]
i = 1
while True:
    if i > 171:
        break
    T_uniform.append(i)
    i += 2

print(f"Size of T_uniform: {len(T_uniform)}")
size_uniform = compute_sumset_size(T_uniform)
print(f"Size of sumset for T_uniform: {size_uniform}")

